    {creditSource && <section className="overflow-hidden rounded-2xl border border-blue-200 bg-background shadow-sm" data-testid="customer-credit-section"><div className="border-b border-blue-100 bg-blue-50 px-3 py-3 sm:px-4"><div><h2 className="text-xs font-black uppercase tracking-wide text-blue-950">Customer Credit</h2><p className="mt-0.5 text-[11px] text-blue-800">Credit sales create receivables. Debt payments reduce receivables.</p></div></div><div className="space-y-3 p-3 sm:p-4"><div className="flex items-end justify-between gap-3"><div><Label className="mb-1 block text-[10px] font-bold uppercase tracking-wide text-muted-foreground">Customer Transaction</Label><p className="text-xs text-muted-foreground">Select the customer before entering a credit sale or payment.</p></div><Button type="button" size="sm" className="min-h-10 shrink-0" onClick={addCustomerCreditSale} disabled={custLoading}><PlusCircle className="mr-1.5 h-4 w-4" />Add Customer</Button></div>{custLoading?<div className="rounded-xl border border-slate-200 bg-slate-50 px-3 py-3 text-sm text-muted-foreground">Loading canonical customer receivables…</div>:customerCreditSales.length===0?<div className="rounded-xl border border-dashed border-blue-200 bg-white px-3 py-4 text-sm text-muted-foreground">No Customer Credit transaction has been added.</div>:<div className="grid grid-cols-1 gap-3">{customerCreditSales.map((entry,index)=><CustomerCreditSalesSource key={entry.id} entry={entry} idx={index} onRemove={removeCustomerCreditSale} onUpdate={updateCustomerCreditSale} customers={customers} currency={currency} customerSearch={customerSearch} onCustomerSearch={setCustomerSearch} onSelectCustomer={()=>selectCustomerForCredit(entry.customer_id)} onRecordPayment={recordCustomerCreditPayment} isRecordingPayment={isRecordingCustomerDebtPayment} disabled={isSubmitting}/>)}</div>}</div></section>}
